CREATE TABLE `cdr_files` (
  `file_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'File ID',
  `provider_id` int unsigned NOT NULL COMMENT 'Provider ID',
  `filename` varchar(255) NOT NULL COMMENT 'Filename',
  `file_created_at` timestamp NOT NULL COMMENT 'File Created At',
  `file_size` int NOT NULL DEFAULT '0' COMMENT 'File Size',
  `content` mediumblob NOT NULL,
  `status` varchar(50) NOT NULL COMMENT 'Status',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Created At',
  `processed_at` timestamp NULL DEFAULT NULL COMMENT 'Processed At',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Updated At',
  `updated_by` int unsigned DEFAULT '0' COMMENT 'Updated By',
  `created_by` int unsigned DEFAULT '0' COMMENT 'Created By',
  `file_path` varchar(255) DEFAULT NULL COMMENT 'File Path',
  PRIMARY KEY (`file_id`),
  UNIQUE KEY `CDR_FILES_FILENAME` (`filename`),
  KEY `CDR_FILES_PROVIDER_ID_SERVICE_PROVIDERS_PROVIDER_ID` (`provider_id`),
  CONSTRAINT `CDR_FILES_PROVIDER_ID_SERVICE_PROVIDERS_PROVIDER_ID` FOREIGN KEY (`provider_id`) REFERENCES `service_providers` (`provider_id`) ON DELETE CASCADE
