--
-- Table structure for table `line_usage`
--

DROP TABLE IF EXISTS `line_usage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `line_usage` (
  `usage_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'Usage ID',
  `cdr_file_id` int unsigned NOT NULL COMMENT 'CDR File ID',
  `provider_id` int unsigned NOT NULL COMMENT 'Provider ID',
  `sim_number` varchar(50) DEFAULT NULL COMMENT 'SIM Number',
  `sim_id` varchar(50) DEFAULT NULL COMMENT 'SIM ID',
  `called_number` varchar(50) DEFAULT NULL COMMENT 'Called Number',
  `date_usage` datetime DEFAULT NULL COMMENT 'Date of Usage',
  `value_operator` float(10,0) DEFAULT NULL COMMENT 'Value Operator',
  `unit_type_operator` varchar(10) DEFAULT NULL COMMENT 'Unit Type Operator',
  `value_our` float(10,0) DEFAULT NULL COMMENT 'Value Our',
  `unit_type_our` varchar(10) DEFAULT NULL COMMENT 'Unit Type Our',
  `cost` decimal(12,4) DEFAULT '0.0000' COMMENT 'Cost',
  `cost_our` decimal(12,4) DEFAULT '0.0000' COMMENT 'Cost Our',
  `is_ok` smallint unsigned DEFAULT '0' COMMENT 'Is OK',
  `mode` smallint unsigned DEFAULT '0' COMMENT 'Mode',
  `is_incoming` smallint unsigned DEFAULT '0' COMMENT 'Is Incoming',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Created At',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Updated At',
  `created_by` int unsigned DEFAULT NULL COMMENT 'Created By',
  `updated_by` int unsigned DEFAULT NULL COMMENT 'Updated By',
  `id_sp_call_type` smallint unsigned DEFAULT NULL COMMENT 'SP Call Type ID (1=Voice, 2=SMS, 3=Data)',
  `id_sp_call_group` int unsigned DEFAULT NULL COMMENT 'SP Call Group ID',
  `id_customer_contract` int unsigned DEFAULT NULL COMMENT 'Customer Contract ID',
  `id_customer_order` int unsigned DEFAULT NULL COMMENT 'Customer Order ID',
  `id_prepaid` int unsigned DEFAULT NULL COMMENT 'Prepaid ID',
  `id_customer` int unsigned DEFAULT NULL COMMENT 'Customer ID',
  `id_state` int unsigned DEFAULT NULL COMMENT 'State ID',
  `id_country` int unsigned DEFAULT NULL COMMENT 'Country ID',
  `destination_type` varchar(50) DEFAULT NULL COMMENT 'Destination Type',
  `is_rollover` smallint unsigned DEFAULT '0' COMMENT 'Is Rollover',
  `account_id` int unsigned DEFAULT NULL COMMENT 'Account Identifier (e.g., Acnt from Comsat, Account ID from Starlink)',
  `invoice_number` varchar(50) DEFAULT NULL COMMENT 'Invoice Number (e.g., InvNo from Comsat, External Ref from AST)',
  `charge_type` varchar(50) DEFAULT NULL COMMENT 'Charge Type (e.g., TRAFFIC from Comsat, Charge Type from AST)',
  `credit_debit` varchar(10) DEFAULT NULL COMMENT 'Credit or Debit Indicator (e.g., D for Debit, C for Credit)',
  `message_ref` varchar(50) DEFAULT NULL COMMENT 'Message Reference Number (e.g., MsgRef from Comsat)',
  `platform_id` varchar(50) DEFAULT NULL COMMENT 'Platform Identifier (e.g., PlatfId from Comsat)',
  `platform_name` varchar(255) DEFAULT NULL COMMENT 'Platform Name (e.g., PlatfNam from Comsat)',
  `ocean_region` varchar(50) DEFAULT NULL COMMENT 'Ocean Region Code (e.g., OceReg from Comsat)',
  `sub_account` varchar(50) DEFAULT NULL COMMENT 'Sub-Account Code (e.g., Sbac from Comsat)',
  `originating_number` varchar(50) DEFAULT NULL COMMENT 'Originating Number or Identifier (e.g., Orig from Comsat)',
  `number_type` varchar(50) DEFAULT NULL COMMENT 'Number Type (e.g., NumTyp from Comsat, BGAN, FIXED)',
  `short_code` varchar(50) DEFAULT NULL COMMENT 'Short Code or Service Code (e.g., ShCod from Comsat)',
  `country` varchar(50) DEFAULT NULL COMMENT 'Country Code or Name (e.g., Cntry from Comsat)',
  `service_code` varchar(50) DEFAULT NULL COMMENT 'Service Code (e.g., SvcCod from Comsat)',
  `service_name` varchar(255) DEFAULT NULL COMMENT 'Service Name (e.g., SvcNam from Comsat)',
  `service_subtype` varchar(50) DEFAULT NULL COMMENT 'Service Subtype (e.g., SvcSub from Comsat)',
  `rate_period` varchar(10) DEFAULT NULL COMMENT 'Rate Period (e.g., RatPer from Comsat, S for Standard)',
  `billing_volume` float(10,0) DEFAULT NULL COMMENT 'Billing Volume (e.g., BillV from Comsat)',
  `connection_volume` float(10,0) DEFAULT NULL COMMENT 'Connection Volume (e.g., ConnV from Comsat)',
  `satellite_volume` float(10,0) DEFAULT NULL COMMENT 'Satellite Volume (e.g., SatV from Comsat)',
  `satellite_rate` float(10,0) DEFAULT NULL COMMENT 'Satellite Rate (e.g., SatRat from Comsat)',
  `destination_rate` float(10,0) DEFAULT NULL COMMENT 'Destination Rate (e.g., DestRat from Comsat)',
  `satellite_charge` decimal(12,4) DEFAULT '0.0000' COMMENT 'Satellite Charge (e.g., SatChg from Comsat)',
  `destination_charge` decimal(12,4) DEFAULT '0.0000' COMMENT 'Destination Charge (e.g., DestChg from Comsat)',
  `facility_charge` decimal(12,4) DEFAULT '0.0000' COMMENT 'Facility Charge (e.g., FacChg from Comsat)',
  `discount_amount` decimal(12,4) DEFAULT '0.0000' COMMENT 'Discount Amount (e.g., Disc from Comsat)',
  `discount_type` varchar(10) DEFAULT NULL COMMENT 'Discount Type (e.g., DiscTyp from Comsat, N for None)',
  `currency` varchar(10) DEFAULT NULL COMMENT 'Currency (e.g., Cur from Comsat, USD)',
  `isp` varchar(50) DEFAULT NULL COMMENT 'Internet Service Provider (e.g., ISP from Comsat)',
  `carrier` varchar(50) DEFAULT NULL COMMENT 'Carrier Name (e.g., Carrier from Comsat)',
  `originating_country` varchar(50) DEFAULT NULL COMMENT 'Originating Country (e.g., OrigCntry from Comsat)',
  `invoice_reference` varchar(50) DEFAULT NULL COMMENT 'Invoice Reference (e.g., InvRef from Comsat)',
  `usf_applied` varchar(10) DEFAULT NULL COMMENT 'Universal Service Fund Applied (e.g., USFApplied from Comsat)',
  `rate_type` varchar(50) DEFAULT NULL COMMENT 'Rate Type (e.g., RatTyp from Comsat)',
  `package_type` varchar(255) DEFAULT NULL COMMENT 'Package Type (e.g., PackTyp from Comsat)',
  `call_serial_number` varchar(50) DEFAULT NULL COMMENT 'Call Serial Number (e.g., CallSerNum from Comsat)',
  `parse_errors` text COMMENT 'Parsing Errors (e.g., Missing MobNo, Invalid date format)',
  PRIMARY KEY (`usage_id`),
  KEY `LINE_USAGE_CDR_FILE_ID_CDR_FILES_FILE_ID` (`cdr_file_id`),
  KEY `LINE_USAGE_PROVIDER_ID_SERVICE_PROVIDERS_PROVIDER_ID` (`provider_id`),
  KEY `LINE_USAGE_ACCOUNT_ID_PROVIDER_ACCOUNTS_ACCOUNT_ID` (`account_id`),
  CONSTRAINT `LINE_USAGE_ACCOUNT_ID_PROVIDER_ACCOUNTS_ACCOUNT_ID` FOREIGN KEY (`account_id`) REFERENCES `provider_accounts` (`account_id`) ON DELETE SET NULL,
  CONSTRAINT `LINE_USAGE_CDR_FILE_ID_CDR_FILES_FILE_ID` FOREIGN KEY (`cdr_file_id`) REFERENCES `cdr_files` (`file_id`) ON DELETE CASCADE,
  CONSTRAINT `LINE_USAGE_PROVIDER_ID_SERVICE_PROVIDERS_PROVIDER_ID` FOREIGN KEY (`provider_id`) REFERENCES `service_providers` (`provider_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11149 DEFAULT CHARSET=utf8mb3 COMMENT='Line Usage';
/*!40101 SET character_set_client = @saved_cs_client */;

